```php
namespace Symfony\Component\Messenger\Middleware;

final class StackHelper implements StackInterface
{
    /** @var MiddlewareInterface[] */
    private array $stack;

    public function __construct(array $stack = [])
    {
        $this->stack = $stack;
    }

    public function push(MiddlewareInterface $middleware): void
    {
        array_push($this->stack, $middleware);
    }

    public function top(): MiddlewareInterface
    {
        if (!$this->stack) {
            throw new \LogicException('Stack is empty, you should not call this method.');
        }

        return end($this->stack);
    }

    public function next(): StackInterface
    {
        if (!$this->stack) {
            throw new \LogicException('Stack is empty, you should not call this method.');
        }

        $middleware = array_pop($this->stack);

        return new self($this->stack);
    }

    public function pop(): MiddlewareInterface
    {
        if (!$this->stack) {
            throw new \LogicException('Stack is empty, you should not call this method.');
        }

        return array_pop($this->stack);
    }
}
```

